import fs from 'node:fs';
import assert from 'node:assert/strict';
import vm from 'node:vm';
import { createHash } from 'node:crypto';

const directory = '/private/tmp/jobs53-jlr4-vUoMHe';
const phase = process.argv[2];
assert.ok(phase === 'red' || phase === 'green');
const path = phase === 'red' ? '/private/tmp/jobs53-wait-grammar-v2-Zdvnz1/capture.mjs' : `${directory}/capture.mjs`;
const before = fs.lstatSync(path);
assert.ok(before.isFile() && !before.isSymbolicLink() && before.size <= 32768);
assert.equal(fs.realpathSync(path), path);
const handle = fs.openSync(path, fs.constants.O_RDONLY | fs.constants.O_NOFOLLOW);
let bytes;
try {
  bytes = Buffer.alloc(before.size);
  let offset = 0;
  while (offset < bytes.length) {
    const count = fs.readSync(handle, bytes, offset, bytes.length - offset, null);
    assert.ok(count > 0);
    offset += count;
  }
  assert.equal(fs.readSync(handle, Buffer.alloc(1), 0, 1, null), 0);
  for (const after of [fs.fstatSync(handle), fs.lstatSync(path)]) for (const key of ['dev', 'ino', 'size', 'mode', 'mtimeMs', 'ctimeMs']) assert.equal(after[key], before[key]);
} finally { fs.closeSync(handle); }
const sourceSHA256 = createHash('sha256').update(bytes).digest('hex');
if (phase === 'red') assert.equal(sourceSHA256, 'd592affcd4a638972adce1d4489808cbcea9da166d4b0f61a2858950a0a3605c');
const source = bytes.toString('utf8');
const start = source.indexOf('    const advance = () => {');
const end = source.indexOf('    killTimer = setTimeout', start);
assert.ok(start >= 0 && end > start);
const fragment = source.slice(start, end);
const fixture = `
  let failure;
  let finalized = false;
  let anchorExited = false;
  let childClosed = false;
  let anchorConfirmed = false;
  let anchorLeaseClosed = false;
  let subject;
  let subjectStatus;
  let protocolPid;
  let gateReleased = false;
  let ackReleased = false;
  let ownerReleased = false;
  let releaseMarkers = 0;
  const sourceRecords = { READY: 0, PID: 0, CAPTURED: 0, DONE: 0 };
  const ended = new Set();
  const child = { pid: 700 };
  const writes = [];
  const events = [];
  const event = (kind, fields) => events.push({ kind, ...fields });
  const send = (fd, bytes, category, kind) => writes.push({ fd, hex: bytes.toString('hex'), category, kind });
  const killAnchoredGroup = () => {};
  const entry = { id: caseId, gateFd: caseId === 1 ? 3 : 4, ackFd: caseId === 1 ? 4 : 3 };
  ${fragment}
  const receive = text => line(Buffer.from(text));
  const parentRelease = () => stdoutLine(Buffer.from('RELEASE'));
`;
const tests = [{ name: 'source READY may arrive before supervisor identity without any release', caseId: 1, body: `receive('READY'); assert.equal(writes.length, 0);` }];
if (phase === 'green') {
  const orders = [ ['READY', 'PID:702', 'CAPTURED'], ['READY', 'CAPTURED', 'PID:702'], ['PID:702', 'READY', 'CAPTURED'], ['PID:702', 'CAPTURED', 'READY'], ['CAPTURED', 'READY', 'PID:702'], ['CAPTURED', 'PID:702', 'READY'] ];
  for (const caseId of [1, 2]) for (const [index, order] of orders.entries()) tests.push({ name: `case${caseId} cross-writer order${index + 1} withholds all sends until identity`, caseId, body: `
    ${JSON.stringify(order)}.forEach(receive);
    if (caseId === 1) parentRelease();
    assert.equal(writes.length, 0);
    receive('ANCHOR:700'); assert.equal(writes.length, 0);
    receive('SUBJECT:701');
    assert.equal(writes.length, 1); assert.equal(writes[0].fd, entry.gateFd); assert.equal(writes[0].hex, '676f0a');
    receive('DONE'); assert.equal(writes.length, 2); assert.equal(writes[1].fd, entry.ackFd); assert.equal(writes[1].hex, '646f6e650a');
    if (caseId === 2) parentRelease();
    receive('SUBJECT_EXIT:0'); assert.equal(writes.length, 2);
    ended.add(1); advance(); assert.equal(writes.length, 2);
    ended.add(2); advance(); assert.equal(writes.length, 3); assert.equal(writes[2].fd, 8); assert.equal(writes[2].hex, '72656c656173650a');
    advance(); assert.equal(writes.length, 3);
  ` });
  tests.push({ name: 'case1 readiness and identity never substitute for parent RELEASE', caseId: 1, body: `
    ['ANCHOR:700','SUBJECT:701','PID:702','READY','CAPTURED'].forEach(receive);
    assert.equal(writes.length, 0); parentRelease(); assert.equal(writes.length, 1);
  ` });
  tests.push({ name: 'DONE before identity cannot release acknowledgement or gate', caseId: 2, body: `
    ['READY','PID:702','CAPTURED','DONE'].forEach(receive); assert.equal(writes.length, 0);
    receive('ANCHOR:700'); assert.equal(writes.length, 0); receive('SUBJECT:701'); assert.equal(writes.length, 2);
  ` });
  for (const record of ['READY', 'PID:702', 'CAPTURED', 'DONE']) tests.push({ name: `duplicate ${record} refused`, caseId: 1, body: `receive(${JSON.stringify(record)}); assert.throws(() => receive(${JSON.stringify(record)})); assert.equal(writes.length, 0);` });
  for (const record of ['OTHER', 'READY:1', 'PID:0', 'PID:-2', 'PID: 702', 'PID:0702', 'PID:700', 'PID:9007199254740992']) tests.push({ name: `invalid record ${record} refused`, caseId: 1, body: `assert.throws(() => receive(${JSON.stringify(record)})); assert.equal(writes.length, 0);` });
  tests.push({ name: 'source PID cannot masquerade as later subject identity', caseId: 1, body: `receive('PID:701'); receive('ANCHOR:700'); assert.throws(() => receive('SUBJECT:701')); assert.equal(writes.length, 0);` });
  tests.push({ name: 'duplicate parent RELEASE refused', caseId: 1, body: `parentRelease(); assert.throws(parentRelease); assert.equal(writes.length, 0);` });
  for (const stop of ['failure = new Error("stop")', 'finalized = true', 'anchorExited = true', 'childClosed = true', 'anchorLeaseClosed = true']) tests.push({ name: `no sends when ${stop}`, caseId: 2, body: `
    ['ANCHOR:700','SUBJECT:701','PID:702','READY'].forEach(receive);
    ${stop}; receive('CAPTURED'); assert.equal(writes.length, 0);
  ` });
}
const results = tests.map(test => {
  try { vm.runInNewContext(fixture + test.body, { Buffer, assert, caseId: test.caseId }, { timeout: 1000 }); return { name: test.name, passed: true }; }
